-- 90_VERIFY — [E20261021-DMF0020SAVECLOB] 조회 전용 (전체 F5, 값 입력 없음)
-- * 기대: V1 마커 44 PASS · V2 SPEC/BODY VALID · 오류 0 · 의존 INVALID 0 · V3 ALL_ARGUMENTS IN 33 CLOB · V4 PROC_M IN 33 CLOB · V5 의존 객체 전부 VALID
SET LINESIZE 220 PAGESIZE 500
SET DEFINE OFF
SELECT 'V1 marker' CHK, TYPE, COUNT(*) N FROM USER_SOURCE WHERE NAME='PKG_DMF0020' AND TEXT LIKE '%[E20261021-DMF0020SAVECLOB]%' GROUP BY TYPE
UNION ALL SELECT 'V1 marker', 'TOTAL', COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0020' AND TEXT LIKE '%[E20261021-DMF0020SAVECLOB]%' ORDER BY 2;
SELECT 'V1 judge' CHK, CASE WHEN COUNT(*) = 44 THEN 'PASS' ELSE 'FAIL (expected 44)' END JUDGE FROM USER_SOURCE WHERE NAME='PKG_DMF0020' AND TEXT LIKE '%[E20261021-DMF0020SAVECLOB]%';
SELECT 'V2 status' CHK, O.OBJECT_TYPE, O.STATUS, TO_CHAR(O.LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL,
       (SELECT COUNT(*) FROM USER_ERRORS E WHERE E.NAME=O.OBJECT_NAME AND E.TYPE=O.OBJECT_TYPE AND E.ATTRIBUTE='ERROR') ERR_CNT,
       (SELECT COUNT(*) FROM USER_OBJECTS X WHERE X.STATUS<>'VALID' AND X.OBJECT_NAME IN (SELECT NAME FROM USER_DEPENDENCIES WHERE REFERENCED_NAME='PKG_DMF0020')) DEP_INVALID
  FROM USER_OBJECTS O WHERE O.OBJECT_NAME='PKG_DMF0020' ORDER BY O.OBJECT_TYPE;
SELECT 'V3 args' CHK, OBJECT_NAME, DATA_TYPE, COUNT(*) N, CASE WHEN DATA_TYPE = 'CLOB' AND COUNT(*) = CASE OBJECT_NAME WHEN 'P_DMF0020_SAVE_SCM_MST_FUTURE_PRICE_ALL' THEN 17 ELSE 16 END THEN 'PASS' ELSE 'CHECK' END JUDGE
  FROM USER_ARGUMENTS WHERE PACKAGE_NAME='PKG_DMF0020' AND OBJECT_NAME IN ('P_DMF0020_SAVE_SCM_MST_FUTURE_PRICE_ALL','P_DMF0020_SAVE_SCM_MST_FUTURE_PRICE_POPUP') AND IN_OUT='IN'
 GROUP BY OBJECT_NAME, DATA_TYPE ORDER BY 2, 3;
SELECT 'V4 PROC_M' CHK, PROC_NM, DATA_TP_CD, COUNT(*) N, CASE WHEN DATA_TP_CD='CLOB' AND COUNT(*) = CASE PROC_NM WHEN 'PKG_DMF0020.P_DMF0020_SAVE_SCM_MST_FUTURE_PRICE_ALL' THEN 17 ELSE 16 END THEN 'PASS' ELSE 'FAIL' END JUDGE
  FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM IN ('PKG_DMF0020.P_DMF0020_SAVE_SCM_MST_FUTURE_PRICE_ALL', 'PKG_DMF0020.P_DMF0020_SAVE_SCM_MST_FUTURE_PRICE_POPUP') AND COL_TP_CD='IN' GROUP BY PROC_NM, DATA_TP_CD ORDER BY 2, 3;
SELECT 'V5 dependents' CHK, NAME, TYPE, (SELECT MAX(STATUS) FROM USER_OBJECTS O WHERE O.OBJECT_NAME = D.NAME AND O.OBJECT_TYPE = D.TYPE) STATUS
  FROM (SELECT DISTINCT NAME, TYPE FROM USER_DEPENDENCIES WHERE REFERENCED_NAME = 'PKG_DMF0020' AND REFERENCED_TYPE = 'PACKAGE' AND NAME <> 'PKG_DMF0020') D ORDER BY 2, 3;
SELECT 'V6 residue' CHK, K.KIND, COUNT(S.LINE) N, CASE WHEN COUNT(S.LINE) = 0 THEN 'PASS' ELSE 'FAIL' END JUDGE
  FROM (SELECT 'active REGEXP_SUBSTR in _ALL (outside ORIG comment)' KIND FROM DUAL) K
  LEFT JOIN USER_SOURCE S ON S.NAME = 'PKG_DMF0020' AND S.TYPE = 'PACKAGE BODY' AND S.TEXT LIKE '%,TRIM(REGEXP_SUBSTR(P_%'
   AND S.LINE BETWEEN (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0020' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%PROCEDURE P_DMF0020_SAVE_SCM_MST_FUTURE_PRICE_ALL%')
                  AND (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0020' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%[E20261021-DMF0020SAVECLOB] BEGIN-ORIG A3%')
 GROUP BY K.KIND;
